const entrada = $input.first().json;
const erro = (detalhe) => [{json:{status:'ENTRADA_INVALIDA',detalhe,grupos:null}}];
const dataValida = (s) => { if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null; const d=new Date(s+'T00:00:00Z'); return Number.isFinite(d.valueOf()) && d.toISOString().slice(0,10)===s ? d.valueOf() : null; };
if (!entrada || !Array.isArray(entrada.tarefas)) return erro('tarefas deve ser uma lista');
const referencia=dataValida(entrada.dataReferencia);
if (referencia===null) return erro('dataReferencia deve ser uma data YYYY-MM-DD válida');
if (entrada.tarefas.length===0) return [{json:{status:'SEM_DADOS',dataReferencia:entrada.dataReferencia,total:0,grupos:{atrasadas:[],proximas:[],futuras:[],concluidas:[]}}}];
const ids=new Set(), itens=[];
for (const [i,t] of entrada.tarefas.entries()) {
  if (!t || typeof t !== 'object' || Array.isArray(t)) return erro(`tarefa ${i+1} inválida`);
  if (typeof t.id !== 'string' || !t.id.trim() || ids.has(t.id.trim()) || typeof t.titulo !== 'string' || !t.titulo.trim() || typeof t.concluida !== 'boolean') return erro(`campos inválidos ou id repetido na tarefa ${i+1}`);
  const prazo=dataValida(t.vencimento); if (prazo===null) return erro(`vencimento inválido na tarefa ${i+1}`);
  ids.add(t.id.trim()); itens.push({id:t.id.trim(),titulo:t.titulo.trim(),vencimento:t.vencimento,concluida:t.concluida,diasRestantes:Math.round((prazo-referencia)/86400000)});
}
const grupos={atrasadas:[],proximas:[],futuras:[],concluidas:[]};
for (const t of itens) {
  const {concluida,...resumo}=t;
  const grupo=concluida?'concluidas':t.diasRestantes<0?'atrasadas':t.diasRestantes<=3?'proximas':'futuras';
  grupos[grupo].push(resumo);
}
for (const valores of Object.values(grupos)) valores.sort((a,b)=>a.diasRestantes-b.diasRestantes || a.id.localeCompare(b.id));
return [{json:{status:'RESUMO_OK',dataReferencia:entrada.dataReferencia,total:itens.length,contagens:Object.fromEntries(Object.entries(grupos).map(([k,v])=>[k,v.length])),grupos}}];
